<!doctype html>
<html><head><meta charset="utf-8"><title>{{ $receipt->receipt_number }}</title><style>body{font-family:DejaVu Sans,sans-serif;color:#16352b;padding:40px}h1{margin-bottom:4px}.muted{color:#66756f}.box{border:1px solid #d8e2dc;padding:20px;border-radius:10px;margin-top:25px}table{width:100%;border-collapse:collapse}td{padding:9px;border-bottom:1px solid #eee}.total{font-size:20px;font-weight:bold}</style></head><body><h1>Hope &amp; Care</h1><div class="muted">Official Donation Receipt</div><div class="box"><table><tr><td>Receipt</td><td>{{ $receipt->receipt_number }}</td></tr><tr><td>Date</td><td>{{ $receipt->issued_at->format('d M Y') }}</td></tr><tr><td>Donor</td><td>{{ $donation->anonymous ? 'Anonymous donor' : $donation->donor_name }}</td></tr><tr><td>Email</td><td>{{ $donation->email }}</td></tr><tr><td>Purpose</td><td>{{ $donation->purpose ?: 'General support' }}</td></tr><tr><td>Payment</td><td>{{ strtoupper($donation->payment_method ?: 'Online') }}</td></tr><tr class="total"><td>Amount</td><td>{{ $donation->currency }} {{ number_format((float)$donation->amount, 2) }}</td></tr></table></div><p>Thank you for supporting Hope &amp; Care and the children we serve.</p></body></html>
